/**
 * Checks the live deployment the TWA will point at.
 *
 * A TWA is verified at install time against the origin it opens: the origin must
 * serve the PWA manifest and the 512 px icons Bubblewrap copies, and it must
 * serve `/.well-known/assetlinks.json` naming this package and this certificate.
 * All of that is generated by the Pages build, so Pages has to be deployed
 * before this workflow is useful — and a mismatch has to fail *here* rather than
 * leave an installed app with a visible URL bar.
 *
 * Requests are issued in parallel and without following redirects: the docs
 * require a direct `200`, and `curl` without `-L` (the previous form of this
 * check) rejected a redirect too.
 */

import { isEntrypoint } from '../lib/entrypoint.ts';
import { normalizeFingerprint, formatFingerprint, looseFingerprint } from './fingerprint.ts';
import { requiredEnv, runStep } from './actions.ts';

const HANDLE_ALL_URLS = 'delegate_permission/common.handle_all_urls';
const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] as const;
const FETCH_TIMEOUT_MS = 30_000;

export interface DeploymentExpectations {
  /** `https://host`, no trailing path. */
  readonly origin: string;
  readonly packageId: string;
  /** Canonical (bare, uppercase) keystore fingerprint. */
  readonly fingerprint: string;
  /** Canonical Play App Signing fingerprint, when the deployment uses Play. */
  readonly playFingerprint?: string;
  readonly fetchImpl?: typeof fetch;
}

interface AssetLinkTarget {
  readonly namespace?: unknown;
  readonly package_name?: unknown;
  readonly sha256_cert_fingerprints?: unknown;
}

interface AssetLinkStatement {
  readonly relation?: unknown;
  readonly target?: AssetLinkTarget;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAssetLinkStatement(value: unknown): value is AssetLinkStatement {
  return isRecord(value) && (value.target === undefined || isRecord(value.target));
}

/**
 * Fetches one URL and requires a direct `200`.
 */
export async function fetchOk(url: string, fetchImpl: typeof fetch = fetch): Promise<Uint8Array> {
  let response: Response;
  try {
    response = await fetchImpl(url, {
      redirect: 'manual',
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
    });
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`${url} could not be fetched (${reason})`);
  }
  if (response.status !== 200) {
    throw new Error(`${url} returned HTTP ${response.status}`);
  }
  return new Uint8Array(await response.arrayBuffer());
}

/**
 * Reads the PWA manifest's name, which Bubblewrap copies into the TWA manifest.
 */
export function readManifestName(bytes: Uint8Array): string {
  let manifest: unknown;
  try {
    manifest = JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new Error('The live web manifest is not valid JSON');
  }
  const name = isRecord(manifest) ? manifest.name : undefined;
  if (typeof name !== 'string' || name.length === 0) {
    throw new Error('The live web manifest has no name');
  }
  return name;
}

/**
 * Whether the bytes start with the PNG signature.
 *
 * Bubblewrap downloads these two files and resizes them into the APK's launcher
 * icon; an HTML error page with a 200 status would otherwise become a broken
 * icon at build time with no useful message.
 */
export function isPng(bytes: Uint8Array): boolean {
  return PNG_SIGNATURE.every((byte, index) => bytes[index] === byte);
}

/**
 * Validates the served Digital Asset Links statement.
 *
 * Two rules beyond "the file exists": the statement must grant the URL handling
 * permission, and its fingerprints must be exactly the ones this deployment
 * configures. A stale certificate is a security problem, not just a build
 * problem — an old key could still sign an update Chrome treats as this app.
 */
export function validateAssetLinks(bytes: Uint8Array, expectations: DeploymentExpectations): void {
  let statements: unknown;
  try {
    statements = JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new Error('The live assetlinks.json is not valid JSON');
  }
  if (!Array.isArray(statements)) {
    throw new Error('The live assetlinks.json is not a list of statements');
  }

  const statement = statements.filter(isAssetLinkStatement).find((candidate) => {
    const target = candidate.target;
    return target?.namespace === 'android_app' && target.package_name === expectations.packageId;
  });
  if (!statement) {
    throw new Error(
      `The live assetlinks.json does not name ${expectations.packageId}. Set ANDROID_PACKAGE_ID, redeploy Pages, then retry.`,
    );
  }

  if (!Array.isArray(statement.relation) || !statement.relation.includes(HANDLE_ALL_URLS)) {
    throw new Error('The live assetlinks statement does not handle all URLs');
  }

  const rawFingerprints = statement.target?.sha256_cert_fingerprints;
  if (!Array.isArray(rawFingerprints)) {
    throw new Error(
      `The live assetlinks.json does not contain the keystore fingerprint. Set ANDROID_CERT_SHA256 to ${formatFingerprint(expectations.fingerprint)}, redeploy Pages, then retry.`,
    );
  }
  const served = rawFingerprints.map((value) => String(value));
  const canonicalServed = served.map(looseFingerprint);
  if (!canonicalServed.includes(expectations.fingerprint)) {
    throw new Error(
      `The live assetlinks.json does not contain the keystore fingerprint. Set ANDROID_CERT_SHA256 to ${formatFingerprint(expectations.fingerprint)}, redeploy Pages, then retry.`,
    );
  }

  const expected = new Set([expectations.fingerprint]);
  if (expectations.playFingerprint) {
    expected.add(expectations.playFingerprint);
  }
  const missing = [...expected].filter((value) => !canonicalServed.includes(value));
  if (missing.length > 0) {
    throw new Error(
      `The live assetlinks.json does not contain every configured certificate fingerprint (missing ${missing.join(', ')}). Set the Android variables, redeploy Pages, then retry.`,
    );
  }
  const unexpected = served.filter((value) => !expected.has(looseFingerprint(value))).map((value) => value.toUpperCase());
  if (unexpected.length > 0) {
    throw new Error(
      `The live assetlinks.json names unexpected certificate fingerprints (${unexpected.join(', ')}). Remove stale keys, redeploy Pages, then retry.`,
    );
  }
}

/**
 * Fetches and validates every resource the TWA build depends on.
 */
export async function verifyDeployment(expectations: DeploymentExpectations): Promise<void> {
  const { origin, fetchImpl = fetch } = expectations;
  const [, manifest, icon, maskableIcon, assetLinks] = await Promise.all([
    fetchOk(`${origin}/`, fetchImpl),
    fetchOk(`${origin}/manifest.webmanifest`, fetchImpl),
    fetchOk(`${origin}/icon-512.png`, fetchImpl),
    fetchOk(`${origin}/icon-maskable-512.png`, fetchImpl),
    fetchOk(`${origin}/.well-known/assetlinks.json`, fetchImpl),
  ]);

  const name = readManifestName(manifest);
  console.log(`The live web manifest names "${name}".`);

  if (!isPng(icon)) {
    throw new Error('The live icon-512.png is not a PNG');
  }
  if (!isPng(maskableIcon)) {
    throw new Error('The live icon-maskable-512.png is not a PNG');
  }

  validateAssetLinks(assetLinks, expectations);
}

if (isEntrypoint(import.meta.url)) {
  runStep('Android preflight', async () => {
    const origin = requiredEnv('ANDROID_ORIGIN');
    const packageId = requiredEnv('ANDROID_PACKAGE_ID');
    const fingerprint = normalizeFingerprint(requiredEnv('ANDROID_KEYSTORE_FINGERPRINT'));
    const play = process.env.ANDROID_PLAY_CERT_SHA256?.trim();

    await verifyDeployment({
      origin,
      packageId,
      fingerprint,
      ...(play ? { playFingerprint: normalizeFingerprint(play) } : {}),
    });

    console.log('The live deployment is ready for the TWA build.');
  });
}
